#!/usr/bin/env node
/**
 * Copy the built bundles into the app and generate the static requires Metro
 * needs to ship them.
 *
 * Metro resolves assets from literal require() strings only, so the list of
 * bundles cannot be read at runtime. This script turns content/bundles/manifest.json
 * into src/data/bundled.generated.ts. Run it after `yada package` or `yada manifest`.
 *
 * Unreviewed-dev bundles are copied — the app must be buildable before review
 * happens — but the generated file records their gate, and the app shows it.
 */

import { copyFileSync, existsSync, mkdirSync, readFileSync, readdirSync, rmSync, writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const here = path.dirname(fileURLToPath(import.meta.url));
const appRoot = path.resolve(here, "..");
const repoRoot = path.resolve(appRoot, "../..");
const source = path.join(repoRoot, "content", "bundles");
const target = path.join(appRoot, "assets", "bundles");
const generated = path.join(appRoot, "src", "data", "bundled.generated.ts");

const manifestPath = path.join(source, "manifest.json");
if (!existsSync(manifestPath)) {
  console.error("No content/bundles/manifest.json. Run `yada package` in packages/pipeline first.");
  process.exit(1);
}
const manifest = JSON.parse(readFileSync(manifestPath, "utf8"));

// Study bundles that ship inside the app (decision for build 3, 11 Oct 2026): John's, so its
// Study notes, See also and People work offline from first launch with no R2 publish. Read from
// the fragment `yada package study` writes; every other book downloads on demand.
const SHIPPED_STUDY = ["JHN"];
const fragmentPath = path.join(source, "study.manifest-fragment.json");
const fragment = existsSync(fragmentPath) ? JSON.parse(readFileSync(fragmentPath, "utf8")) : { study: [] };
const study = (fragment.study ?? []).filter((s) => SHIPPED_STUDY.includes(s.book));
for (const book of SHIPPED_STUDY) {
  // Refused, not warned: a build without it would lose John's notes offline without a word.
  if (!study.some((s) => s.book === book)) {
    console.error(`bundles: no study bundle for ${book} in ${fragmentPath}; run \`yada package study\` first`);
    process.exit(1);
  }
}

// John's Understand ships too (build plan Phase 0: "Ship John's bundle in the app, the way study
// notes do"), so the verse sheet works offline from first launch; other books download (DN-05).
const SHIPPED_UNDERSTAND = ["JHN"];
const understand = (manifest.understand ?? []).filter((u) => SHIPPED_UNDERSTAND.includes(u.book));
for (const book of SHIPPED_UNDERSTAND) {
  if (!understand.some((u) => u.book === book)) {
    console.error(`bundles: no Understand bundle for ${book} in the manifest; run \`yada understand ${book}\` and \`yada manifest\` first`);
    process.exit(1);
  }
}

// Build 7's daily content, shipped inside the app so Today works offline from the first launch (lean plan §0):
// Spurgeon's Morning and Evening (public domain) and the day's pictures (pictures-plan.md). Each is optional
// here, so a checkout without them still builds; Today then shows its no-devotional and no-picture states.
import { createHash } from "node:crypto";
const sha = (file) => createHash("sha256").update(readFileSync(file)).digest("hex");
const daily = ["devotional-spurgeon.v1.db"]
  .filter((file) => existsSync(path.join(source, file)))
  .map((file) => ({ file, sha256: sha(path.join(source, file)) }));
const picturesSource = path.join(repoRoot, "content", "pictures");
const pictures = existsSync(path.join(picturesSource, "manifest.json")) ? JSON.parse(readFileSync(path.join(picturesSource, "manifest.json"), "utf8")) : [];

const shipped = [...manifest.bundles, ...study, ...understand, ...daily];
mkdirSync(target, { recursive: true });
const wanted = new Set(shipped.map((b) => b.file));
for (const file of readdirSync(target)) {
  if (!wanted.has(file) && file !== "pictures") rmSync(path.join(target, file), { recursive: true });
}
for (const bundle of shipped) {
  copyFileSync(path.join(source, bundle.file), path.join(target, bundle.file));
}

const picturesTarget = path.join(target, "pictures");
rmSync(picturesTarget, { recursive: true, force: true });
mkdirSync(picturesTarget, { recursive: true });
for (const p of pictures) copyFileSync(path.join(picturesSource, p.file), path.join(picturesTarget, p.file));
const pictureRows = pictures
  .map((p) => `  { day: ${p.day}, part: ${JSON.stringify(p.part ?? "morning")}, image: require(${JSON.stringify(`../../assets/bundles/pictures/${p.file}`)}) as number, title: ${JSON.stringify(p.title)}, by: ${JSON.stringify(p.by)}, from: ${JSON.stringify(p.from)}, licence: ${JSON.stringify(p.licence)}, alt: ${JSON.stringify(p.alt)} },`)
  .join("\n");
writeFileSync(
  path.join(appRoot, "src", "data", "pictures.generated.ts"),
  `// Generated by scripts/sync-bundles.mjs from content/pictures/manifest.json. Do not edit.\n\n` +
    `export interface DayPicture { readonly day: number; readonly part: "morning" | "evening"; readonly image: number; readonly title: string; readonly by: string; readonly from: string; readonly licence: string; readonly alt: string }\n\n` +
    `export const DAY_PICTURES: readonly DayPicture[] = [\n${pictureRows}\n];\n`,
);

const requires = shipped
  .map((b) => `  ${JSON.stringify(b.file)}: require(${JSON.stringify(`../../assets/bundles/${b.file}`)}) as number,`)
  .join("\n");

writeFileSync(
  generated,
  `// Generated by scripts/sync-bundles.mjs from content/bundles/manifest.json. Do not edit.\n\n` +
    `import type { BundleManifest, StudyInfo, UnderstandInfo } from "@yada/schema";\n\n` +
    `export const BUNDLED_MANIFEST: BundleManifest = ${JSON.stringify(manifest, null, 2)};\n\n` +
    `/** Study bundles shipped inside the app; other books download (data/study.ts). */\n` +
    `export const BUNDLED_STUDY: readonly StudyInfo[] = ${JSON.stringify(study, null, 2)};\n\n` +
    `/** Understand bundles shipped inside the app; other books download (data/understand.ts). */\n` +
    `export const BUNDLED_UNDERSTAND: readonly UnderstandInfo[] = ${JSON.stringify(understand, null, 2)};\n\n` +
    `/** Build 7's daily content (Spurgeon), copied like the rest. */\n` +
    `export const BUNDLED_DAILY: readonly { readonly file: string; readonly sha256: string }[] = ${JSON.stringify(daily, null, 2)};\n\n` +
    `export const BUNDLED_ASSETS: Readonly<Record<string, number>> = {\n${requires}\n};\n`,
);

const mb = manifest.bundles.reduce((sum, b) => sum + b.bytes, 0) / 1048576;
console.log(`bundles: ${manifest.bundles.length} copied (${mb.toFixed(1)} MB) -> assets/bundles, src/data/bundled.generated.ts written`);
for (const b of manifest.bundles.filter((b) => b.review_gate === "unreviewed-dev")) {
  console.log(`  ${b.file} is unreviewed-dev: fine for a local build, never for release`);
}

// The dictionary and guide titles Search finds without the books' files (DI-03, IA-06): read from the same bundles.
await import("./sync-dictionary.mjs");
